INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(800, 'exact', '/ɪɡˈzækt/', 'adjective', '{"zh-TW":["精確的；確切的"],"en":["completely accurate; precise"]}', NULL, 'exact amount/location', '[{"en":"The exact cost has not been determined yet.","zh-TW":"確切費用尚未確定。"},{"en":"Please provide the exact date.","zh-TW":"請提供確切日期。"}]', '{"adjective":"exact","adverb":"exactly"}', NULL, 2, 800),
(801, 'exam', '/ɪɡˈzæm/', 'noun', '{"zh-TW":["考試"],"en":["a formal test of knowledge"]}', NULL, 'take an exam / pass an exam', '[{"en":"I have three exams next week.","zh-TW":"我下週有三場考試。"},{"en":"She passed all her exams.","zh-TW":"她通過了所有考試。"}]', '{"noun2":"examination","noun3":"examiner"}', NULL, 1, 801),
(802, 'examine', '/ɪɡˈzæmɪn/', 'verb', '{"zh-TW":["檢查；審查"],"en":["to inspect closely; to test knowledge"]}', NULL, 'examine closely/carefully', '[{"en":"The auditor examined the financial records.","zh-TW":"審計師審查了財務記錄。"},{"en":"We need to examine this issue more closely.","zh-TW":"我們需要更仔細地審查這個問題。"}]', '{"noun":"examination/examiner","verb":"examine"}', NULL, 3, 802),
(803, 'example', '/ɪɡˈzæmpəl/', 'noun', '{"zh-TW":["例子；範例"],"en":["something typical of a group","a model to follow"]}', NULL, 'for example / set an example', '[{"en":"For example, we could reduce costs here.","zh-TW":"例如，我們可以在這裡降低成本。"},{"en":"She sets a good example for new staff.","zh-TW":"她為新員工樹立了好榜樣。"}]', '{"noun":"example","adjective":"exemplary","verb":"exemplify"}', NULL, 3, 803),
(804, 'exceed', '/ɪkˈsiːd/', 'verb', '{"zh-TW":["超過；超出","超過；超越"],"en":["to go beyond a limit or expectation","to go beyond a limit or standard"]}', '{"prefix":{"text":"ex-","meaning":"out (超出)"},"root":{"text":"ceed","meaning":"go (走)"},"logic":"走出去超越界限，即「超過」。"}', 'exceed expectations/limits; exceed expectations / exceed the limit', '[{"en":"Sales exceeded expectations this quarter.","zh-TW":"本季度銷售超出了預期。"},{"en":"Do not exceed the speed limit.","zh-TW":"不要超過速限。"},{"en":"Sales exceeded our expectations.","zh-TW":"銷售額超出了我們的預期。"}]', '{"adjective":"exceeding","adverb":"exceedingly"}', NULL, 2, 804),
(805, 'excellent', '/ˈeksələnt/', 'adjective', '{"zh-TW":["優秀的；極好的"],"en":["extremely good; outstanding"]}', NULL, 'excellent performance/service', '[{"en":"She received excellent feedback from clients.","zh-TW":"她收到了客戶的優秀評價。"},{"en":"The hotel provides excellent service.","zh-TW":"這家飯店提供優質服務。"}]', '{"noun":"excellence","adjective":"excellent"}', NULL, 3, 805),
(806, 'exception', '/ɪkˈsepʃən/', 'noun', '{"zh-TW":["例外"],"en":["something that does not follow a rule"]}', NULL, 'with the exception of / make an exception', '[{"en":"All staff must attend, with no exceptions.","zh-TW":"所有員工必須參加，沒有例外。"},{"en":"We can make an exception in this case.","zh-TW":"在這種情況下我們可以破例。"}]', '{"noun":"exception","adjective":"exceptional","adverb":"exceptionally"}', NULL, 3, 806),
(807, 'excess', '/ɪkˈses/', 'noun / adjective', '{"zh-TW":["過量；多餘的"],"en":["more than necessary or permitted"]}', NULL, 'in excess of / excess baggage', '[{"en":"Costs were in excess of the budget.","zh-TW":"費用超過了預算。"},{"en":"Excess inventory should be sold at a discount.","zh-TW":"多餘的庫存應打折出售。"}]', '{"noun":"excess","adjective":"excessive","adverb":"excessively"}', NULL, 2, 807),
(808, 'exchange', '/ɪksˈtʃeɪndʒ/', 'noun / verb', '{"zh-TW":["交換；兌換"],"en":["to give and receive; a place for trading","to give something and receive something in return"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"change","meaning":"change (改變)"},"logic":"把東西拿出來改變，即「交換」。"}', 'exchange rate / in exchange for; exchange rate / exchange information', '[{"en":"What is today''s exchange rate?","zh-TW":"今天的匯率是多少？"},{"en":"They exchanged business cards at the conference.","zh-TW":"他們在會議上交換了名片。"},{"en":"Can I exchange this shirt for a larger size?","zh-TW":"我可以把這件襯衫換大一號嗎？"},{"en":"They exchanged contact information.","zh-TW":"他們交換了聯絡資訊。"}]', '{"noun":"exchange","verb":"exchange","adjective":"exchangeable"}', NULL, 3, 808),
(809, 'excited', '/ɪkˈsaɪtɪd/', 'adjective', '{"zh-TW":["興奮的；激動的"],"en":["feeling great enthusiasm"]}', NULL, 'get excited / excited about', '[{"en":"We are excited about the new product launch.","zh-TW":"我們對新產品上市感到興奮。"},{"en":"The team is excited to start.","zh-TW":"團隊很期待開始。"}]', '{"adjective":"excited","verb":"excite","noun":"excitement","adjective2":"exciting"}', NULL, 3, 809),
(810, 'exclude', '/ɪkˈskluːd/', 'verb', '{"zh-TW":["排除；排斥"],"en":["to prevent from being included"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"clude","meaning":"close (關閉)"},"logic":"關在外面，即「排除」。"}', 'exclude from; exclude from / exclude the possibility', '[{"en":"Tax is excluded from the listed price.","zh-TW":"標示價格不含稅。"},{"en":"Some items are excluded from the warranty.","zh-TW":"某些物品不在保固範圍內。"},{"en":"The price excludes tax and delivery.","zh-TW":"價格不含稅和運費。"},{"en":"Don''t exclude anyone from the discussion.","zh-TW":"不要把任何人排除在討論之外。"}]', '{"noun":"exclusion","verb":"exclude","adjective":"exclusive"}', NULL, 3, 810),
(811, 'exclusive', '/ɪkˈskluːsɪv/', 'adjective', '{"zh-TW":["獨家的；專屬的"],"en":["limited to one person or group; high-end"]}', NULL, 'exclusive deal/rights', '[{"en":"We signed an exclusive distribution agreement.","zh-TW":"我們簽署了獨家經銷協議。"},{"en":"The hotel caters to an exclusive clientele.","zh-TW":"這家飯店專門服務高端客戶。"}]', '{"noun":"exclusivity","adjective":"exclusive","adverb":"exclusively"}', NULL, 3, 811),
(812, 'execute', '/ˈeksɪkjuːt/', 'verb', '{"zh-TW":["執行；實施"],"en":["to carry out a plan or action"]}', NULL, 'execute a plan/strategy', '[{"en":"The team executed the project flawlessly.","zh-TW":"團隊完美地執行了項目。"},{"en":"The strategy was well executed.","zh-TW":"該策略執行得很好。"}]', '{"noun":"execution/executive","verb":"execute"}', NULL, 3, 812),
(813, 'exempt', '/ɪɡˈzempt/', 'adjective / verb', '{"zh-TW":["免除的；豁免"],"en":["free from an obligation or liability"]}', NULL, 'exempt from tax/duty', '[{"en":"Non-profit organizations are exempt from taxes.","zh-TW":"非營利組織免稅。"},{"en":"Small businesses may be exempted from the regulation.","zh-TW":"小型企業可能免於遵守該法規。"}]', '{"noun":"exemption","verb":"exempt","adjective":"exempt"}', NULL, 2, 813),
(814, 'exercise', '/ˈeksərsaɪz/', 'noun / verb', '{"zh-TW":["運動；行使"],"en":["physical activity; to use a right or power"]}', NULL, 'exercise caution/authority', '[{"en":"Please exercise caution when handling chemicals.","zh-TW":"處理化學品時請小心謹慎。"},{"en":"Shareholders may exercise their voting rights.","zh-TW":"股東可以行使投票權。"}]', '{"noun":"exercise","verb":"exercise"}', NULL, 3, 814),
(815, 'exhaust', '/ɪɡˈzɔːst/', 'verb / noun', '{"zh-TW":["耗盡；排氣"],"en":["to use up completely; waste gases"]}', NULL, 'exhaust all options/resources', '[{"en":"We have exhausted all possible solutions.","zh-TW":"我們已經用盡了所有可能的解決方案。"},{"en":"Vehicle exhaust contributes to air pollution.","zh-TW":"汽車排氣造成空氣污染。"}]', '{"noun":"exhaustion/exhaust","verb":"exhaust","adjective":"exhausting/exhausted/exhaustive"}', NULL, 3, 815),
(816, 'exhibit', '/ɪɡˈzɪbɪt/', 'verb / noun', '{"zh-TW":["展覽；展示","展覽品；展覽"],"en":["to show publicly; a display","an object displayed in a museum","a public display of art or other items"]}', '{"prefix":{"text":"ex-","meaning":"out (外)"},"root":{"text":"hibit","meaning":"hold (持有)"},"logic":"拿出來展示，即「展覽」。"}', 'exhibit at a trade show; art exhibit / exhibit hall / on exhibit', '[{"en":"The company will exhibit at the trade fair.","zh-TW":"公司將在商展上展覽。"},{"en":"The museum has a new exhibit on technology.","zh-TW":"博物館有一個新的科技展覽。"},{"en":"The museum has a new dinosaur exhibit.","zh-TW":"博物館有新的恐龍展覽。"},{"en":"Her paintings are on exhibit at the gallery.","zh-TW":"她的畫作正在畫廊展出。"}]', '{"noun":"exhibit/exhibition/exhibitor","verb":"exhibit"}', NULL, 3, 816),
(817, 'exhibition', '/ˌɛksɪˈbɪʃən/', 'noun', '{"zh-TW":["展覽"],"en":["a public display of art or objects"]}', NULL, 'art exhibition / on exhibition', '[{"en":"The exhibition runs until March.","zh-TW":"展覽持續到三月。"},{"en":"We visited an art exhibition.","zh-TW":"我們參觀了一場藝術展覽。"}]', '{"verb":"exhibit","noun2":"exhibit"}', NULL, 4, 817),
(818, 'exist', '/ɪɡˈzɪst/', 'verb', '{"zh-TW":["存在"],"en":["to be real; to have actual being"]}', NULL, 'already exist / cease to exist', '[{"en":"The problem still exists.","zh-TW":"問題仍然存在。"},{"en":"Does a solution already exist?","zh-TW":"已經有解決方案了嗎？"}]', '{"verb":"exist","noun":"existence","adjective":"existing","adjective2":"existent"}', NULL, 2, 818),
(819, 'expand', '/ɪkˈspænd/', 'verb', '{"zh-TW":["擴展；擴大"],"en":["to increase in size, number, or importance"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"pand","meaning":"spread (展開)"},"logic":"向外展開，即「擴展」。"}', 'expand operations/business; expand business / expand into new markets', '[{"en":"The company plans to expand into new markets.","zh-TW":"公司計劃擴展到新市場。"},{"en":"We need to expand our product range.","zh-TW":"我們需要擴大產品範圍。"},{"en":"The company plans to expand into Asia.","zh-TW":"公司計畫擴展到亞洲。"},{"en":"We need to expand our product range.","zh-TW":"我們需要擴大產品線。"}]', '{"noun":"expansion","verb":"expand"}', NULL, 2, 819),
(820, 'expect', '/ɪkˈspekt/', 'verb', '{"zh-TW":["期望；預期"],"en":["to believe something will happen"]}', NULL, 'expect + to / be expected to', '[{"en":"We expect revenue to increase next year.","zh-TW":"我們預期明年收入會增加。"},{"en":"Employees are expected to follow the dress code.","zh-TW":"員工被期望遵守服裝規定。"}]', '{"noun":"expectation","verb":"expect","adjective":"expected"}', NULL, 2, 820),
(821, 'expedite', '/ˈekspədaɪt/', 'verb', '{"zh-TW":["加快；促進"],"en":["to make a process happen more quickly"]}', NULL, 'expedite the process/delivery', '[{"en":"We can expedite shipping for an extra fee.","zh-TW":"我們可以加收費用加快出貨。"},{"en":"Please expedite the approval process.","zh-TW":"請加快審批流程。"}]', '{"verb":"expedite","adjective":"expedited"}', NULL, 3, 821),
(822, 'expenditure', '/ɪkˈspendɪtʃər/', 'noun', '{"zh-TW":["支出；開支"],"en":["the action of spending money; an amount spent"]}', NULL, 'capital/government expenditure', '[{"en":"Total expenditure exceeded the budget.","zh-TW":"總支出超過了預算。"},{"en":"Capital expenditure was reduced this year.","zh-TW":"今年資本支出減少了。"}]', '{"noun":"expenditure","verb":"expend"}', NULL, 4, 822),
(823, 'expense', '/ɪkˈspens/', 'noun', '{"zh-TW":["費用；開支"],"en":["the cost of something; money spent"]}', NULL, 'at the expense of / business expense', '[{"en":"Travel expenses will be reimbursed.","zh-TW":"差旅費用將報銷。"},{"en":"Profit should not come at the expense of quality.","zh-TW":"利潤不應以犧牲品質為代價。"}]', '{"noun":"expense","adjective":"expensive"}', NULL, 3, 823),
(824, 'experience', '/ɪkˈspɪriəns/', 'noun / verb', '{"zh-TW":["經驗；體驗"],"en":["knowledge gained through involvement; to encounter"]}', NULL, 'work/customer experience', '[{"en":"Do you have experience in project management?","zh-TW":"你有項目管理經驗嗎？"},{"en":"Customers experienced technical difficulties.","zh-TW":"客戶遇到了技術困難。"}]', '{"noun":"experience","verb":"experience","adjective":"experienced"}', NULL, 4, 824),
(825, 'experiment', '/ɪkˈsperɪmənt/', 'noun / verb', '{"zh-TW":["實驗；試驗"],"en":["a scientific test; to try something new"]}', NULL, 'conduct an experiment', '[{"en":"The team conducted an experiment to test the theory.","zh-TW":"團隊進行了實驗來測試理論。"},{"en":"We are experimenting with new marketing channels.","zh-TW":"我們正在嘗試新的行銷渠道。"}]', '{"noun":"experiment/experimentation","verb":"experiment","adjective":"experimental"}', NULL, 4, 825),
(826, 'expert', '/ˈekspɜːrt/', 'noun / adjective', '{"zh-TW":["專家；專業的"],"en":["a person with great knowledge in a subject"]}', NULL, 'industry/subject expert', '[{"en":"She is an expert in international trade.","zh-TW":"她是國際貿易專家。"},{"en":"We consulted an expert on tax law.","zh-TW":"我們諮詢了一位稅法專家。"}]', '{"noun":"expert/expertise","adjective":"expert"}', NULL, 2, 826),
(827, 'expire', '/ɪkˈspaɪər/', 'verb', '{"zh-TW":["到期；過期"],"en":["to come to the end of validity"]}', NULL, 'expire on/contract expires', '[{"en":"Your contract expires at the end of the month.","zh-TW":"你的合約月底到期。"},{"en":"The coupon expired yesterday.","zh-TW":"優惠券昨天過期了。"}]', '{"noun":"expiration/expiry","verb":"expire","adjective":"expired"}', NULL, 2, 827),
(828, 'explain', '/ɪkˈspleɪn/', 'verb', '{"zh-TW":["解釋；說明"],"en":["to make something clear"]}', NULL, 'explain how/why', '[{"en":"Can you explain the procedure?","zh-TW":"你能解釋一下流程嗎？"},{"en":"She explained why the project was delayed.","zh-TW":"她解釋了為什麼項目延遲了。"}]', '{"noun":"explanation","verb":"explain","adjective":"explanatory"}', NULL, 3, 828),
(829, 'explicit', '/ɪkˈsplɪsɪt/', 'adjective', '{"zh-TW":["明確的；清楚的"],"en":["stated clearly and in detail"]}', NULL, 'explicit instructions/consent', '[{"en":"The contract contains explicit terms.","zh-TW":"合約包含明確的條款。"},{"en":"You need explicit permission to proceed.","zh-TW":"你需要明確的許可才能繼續。"}]', '{"adjective":"explicit","adverb":"explicitly"}', NULL, 3, 829),
(830, 'exploit', '/ɪkˈsplɔɪt/', 'verb', '{"zh-TW":["利用；開發"],"en":["to make full use of; to use unfairly"]}', NULL, 'exploit resources/opportunities', '[{"en":"We should exploit this market opportunity.","zh-TW":"我們應該利用這個市場機會。"},{"en":"The company exploited cheap labor.","zh-TW":"公司剝削了廉價勞動力。"}]', '{"noun":"exploitation","verb":"exploit"}', NULL, 3, 830),
(831, 'explore', '/ɪkˈsplɔːr/', 'verb', '{"zh-TW":["探索；調查"],"en":["to examine or investigate thoroughly"]}', NULL, 'explore options/possibilities', '[{"en":"Let''s explore all available options.","zh-TW":"讓我們探索所有可用的選項。"},{"en":"The team explored new business models.","zh-TW":"團隊探索了新的商業模式。"}]', '{"noun":"exploration/explorer","verb":"explore","adjective":"exploratory"}', NULL, 3, 831),
(832, 'export', '/ˈekspɔːrt/', 'noun / verb', '{"zh-TW":["出口；輸出"],"en":["to sell goods to another country"]}', NULL, 'export goods/data', '[{"en":"Japan exports electronics worldwide.","zh-TW":"日本向全球出口電子產品。"},{"en":"Exports grew by 8% last year.","zh-TW":"去年出口增長了8%。"}]', '{"noun":"export/exporter","verb":"export"}', NULL, 2, 832),
(833, 'expose', '/ɪkˈspoʊz/', 'verb', '{"zh-TW":["暴露；揭發"],"en":["to make visible; to reveal","to make visible or reveal"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把東西放到外面讓人看到，即「暴露」。"}', 'expose to risk/information; expose to / expose the truth', '[{"en":"Workers were exposed to harmful chemicals.","zh-TW":"工人暴露在有害化學品中。"},{"en":"The investigation exposed fraud in the company.","zh-TW":"調查揭發了公司的詐騙行為。"},{"en":"Children should not be exposed to violence.","zh-TW":"兒童不應暴露在暴力之下。"},{"en":"The journalist exposed the corruption scandal.","zh-TW":"記者揭發了貪腐醜聞。"}]', '{"noun":"exposure","verb":"expose","adjective":"exposed"}', NULL, 2, 833),
(834, 'extend', '/ɪkˈstend/', 'verb', '{"zh-TW":["延長；擴展","延伸；延長"],"en":["to make longer or larger"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"tend","meaning":"stretch (伸展)"},"logic":"向外伸展，即「延伸」。"}', 'extend a deadline/contract; extend a deadline / extend an invitation', '[{"en":"Can we extend the deadline by one week?","zh-TW":"我們可以將截止日期延長一週嗎？"},{"en":"The company extended its operations to Asia.","zh-TW":"公司將業務擴展到亞洲。"},{"en":"Can we extend the deadline by one week?","zh-TW":"我們可以把截止期限延長一週嗎？"},{"en":"The road extends for 200 kilometers.","zh-TW":"這條路延伸了200公里。"}]', '{"noun":"extension","verb":"extend","adjective":"extensive/extended","adjective2":"extended"}', NULL, 2, 834),
(835, 'extensive', '/ɪkˈstensɪv/', 'adjective', '{"zh-TW":["廣泛的；大量的"],"en":["covering a large area or having great range","covering a large area or having a wide scope"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"tens","meaning":"stretch (伸展)"},"suffix":{"text":"-ive","meaning":"having quality (具有…特質)"},"logic":"具有向外伸展特質的，即「廣泛的」。"}', 'extensive experience/research; extensive research / extensive experience / extensive damage', '[{"en":"She has extensive experience in finance.","zh-TW":"她有豐富的金融經驗。"},{"en":"Extensive research was conducted.","zh-TW":"進行了廣泛的研究。"},{"en":"She has extensive experience in marketing.","zh-TW":"她在行銷方面有豐富的經驗。"},{"en":"The storm caused extensive damage.","zh-TW":"暴風雨造成了大範圍的損害。"}]', '{"adjective":"extensive","adverb":"extensively","noun":"extent"}', NULL, 3, 835),
(836, 'external', '/ɪkˈstɜːrnəl/', 'adjective', '{"zh-TW":["外部的；外在的"],"en":["coming from outside"]}', NULL, 'external factors/audit', '[{"en":"External factors affected the company''s performance.","zh-TW":"外部因素影響了公司的績效。"},{"en":"An external audit will be conducted.","zh-TW":"將進行外部審計。"}]', '{"adjective":"external","adverb":"externally"}', NULL, 3, 836),
(837, 'extract', '/ɪkˈstrækt/', 'verb / noun', '{"zh-TW":["提取；摘錄"],"en":["to remove or obtain"]}', NULL, 'extract data/information', '[{"en":"We need to extract data from the system.","zh-TW":"我們需要從系統中提取數據。"},{"en":"The dentist extracted the tooth.","zh-TW":"牙醫拔了那顆牙。"}]', '{"noun":"extract/extraction","verb":"extract"}', NULL, 3, 837),
(838, 'extraordinary', '/ɪkˈstrɔːrdəneri/', 'adjective', '{"zh-TW":["非凡的；特別的"],"en":["very unusual or remarkable"]}', NULL, 'extraordinary achievement/circumstances', '[{"en":"She showed extraordinary leadership.","zh-TW":"她展示了非凡的領導力。"},{"en":"Due to extraordinary circumstances, the event was cancelled.","zh-TW":"由於特殊情況，活動被取消了。"}]', '{"adjective":"extraordinary","adverb":"extraordinarily"}', NULL, 5, 838),
(839, 'eye', '/aɪ/', 'noun', '{"zh-TW":["眼睛；注意"],"en":["the organ of sight","careful attention"]}', NULL, 'keep an eye on / eye-catching', '[{"en":"Keep an eye on the budget.","zh-TW":"留意預算。"},{"en":"The design is very eye-catching.","zh-TW":"這個設計非常吸睛。"}]', '{"noun":"eye","noun2":"eyesight"}', NULL, 1, 839),
(840, 'fabricate', '/ˈfæbrɪkeɪt/', 'verb', '{"zh-TW":["捏造；製造"],"en":["to invent false information; to construct"]}', NULL, 'fabricate evidence/a story', '[{"en":"He was accused of fabricating evidence.","zh-TW":"他被指控捏造證據。"},{"en":"The parts are fabricated in our factory.","zh-TW":"零件在我們工廠製造。"}]', '{"noun":"fabrication","verb":"fabricate"}', NULL, 3, 840),
(841, 'face', '/feɪs/', 'verb / noun', '{"zh-TW":["面對；面臨"],"en":["to confront; the front of something"]}', NULL, 'face challenges/problems', '[{"en":"The company faces several challenges.","zh-TW":"公司面臨幾項挑戰。"},{"en":"We must face the reality of budget cuts.","zh-TW":"我們必須面對預算削減的現實。"}]', '{"noun":"face","verb":"face"}', NULL, 1, 841),
(842, 'facilitate', '/fəˈsɪlɪteɪt/', 'verb', '{"zh-TW":["促進；使便利"],"en":["to make an action or process easier"]}', NULL, 'facilitate communication/growth', '[{"en":"Technology facilitates remote collaboration.","zh-TW":"技術促進了遠端協作。"},{"en":"The mediator facilitated the discussion.","zh-TW":"調解人促進了討論。"}]', '{"noun":"facilitation/facilitator","verb":"facilitate"}', NULL, 4, 842),
(843, 'facility', '/fəˈsɪləti/', 'noun', '{"zh-TW":["設施；場所"],"en":["a building or place for a particular purpose"]}', NULL, 'manufacturing/training facility', '[{"en":"The company opened a new manufacturing facility.","zh-TW":"公司開設了新的生產設施。"},{"en":"Our facilities are available for conferences.","zh-TW":"我們的設施可供會議使用。"}]', '{"noun":"facility"}', NULL, 3, 843),
(844, 'fact', '/fækt/', 'noun', '{"zh-TW":["事實"],"en":["something known to be true"]}', NULL, 'in fact / as a matter of fact', '[{"en":"In fact, sales increased by 20%.","zh-TW":"事實上，銷售增長了20%。"},{"en":"We need facts, not opinions.","zh-TW":"我們需要事實，不是意見。"}]', '{"noun":"fact","adjective":"factual","adverb":"factually"}', NULL, 1, 844),
(845, 'factor', '/ˈfæktər/', 'noun', '{"zh-TW":["因素；要素","因素"],"en":["a circumstance that contributes to a result"]}', '{"root":{"text":"fact","meaning":"make/do (做)"},"suffix":{"text":"-or","meaning":"that which (…的東西)"},"logic":"促成某事發生的東西，即「因素」。"}', 'key/determining factor; key factor / risk factor / contributing factor', '[{"en":"Cost is a major factor in the decision.","zh-TW":"成本是決策中的主要因素。"},{"en":"Several factors contributed to the failure.","zh-TW":"幾個因素導致了失敗。"},{"en":"Cost is an important factor in this decision.","zh-TW":"成本是這個決策中的重要因素。"},{"en":"Several factors contributed to the delay.","zh-TW":"多項因素導致了延遲。"}]', '{"noun":"factor","verb":"factor","adjective":"factorial"}', NULL, 2, 845),
