(847, 'fail', '/feɪl/', 'verb', '{"zh-TW":["失敗；未能"],"en":["to be unsuccessful; to neglect"]}', NULL, 'fail to meet/deliver', '[{"en":"The project failed to meet its objectives.","zh-TW":"該項目未能達成目標。"},{"en":"The business failed within two years.","zh-TW":"這家企業在兩年內倒閉了。"}]', '{"noun":"failure","verb":"fail"}', NULL, 1, 847),
(848, 'fair', '/fer/', 'adjective / noun', '{"zh-TW":["公平的；展覽會"],"en":["treating people equally; a commercial exhibition"]}', NULL, 'fair price/trade fair', '[{"en":"We offer fair prices to all customers.","zh-TW":"我們對所有客戶提供公平的價格。"},{"en":"We met potential clients at the trade fair.","zh-TW":"我們在商展上認識了潛在客戶。"}]', '{"noun":"fairness","adjective":"fair","adverb":"fairly"}', NULL, 1, 848),
(849, 'fall', '/fɔːl/', 'verb', '{"zh-TW":["下降；落下；秋天"],"en":["to drop down","to decrease","autumn"]}', NULL, 'fall behind / fall short', '[{"en":"Profits fell by 15% this quarter.","zh-TW":"本季利潤下降了15%。"},{"en":"The results fell short of expectations.","zh-TW":"結果未達預期。"}]', '{"verb":"fall","noun":"fall","noun2":"downfall"}', NULL, 1, 849);
