(893, 'flag', '/flæɡ/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】旗子；旗幟","【次要意義-動詞】衰弱；精力下降；熱情減退","【次要意義-動詞】標記；標示（需注意之處）"],"en":["[primary - noun] a piece of cloth used as a symbol or signal","[secondary - verb] to become tired or less enthusiastic","[secondary - verb] to mark something for attention"]}', NULL, 'flag down / energy flags / flag a concern', '[{"en":"His enthusiasm for the project began to flag after months of setbacks.","zh-TW":"經過幾個月的挫折後，他對這個專案的熱情開始消退。"},{"en":"The editor flagged several errors in the report.","zh-TW":"編輯在報告中標記了幾個錯誤。"},{"en":"Sales flagged in the third quarter due to market uncertainty.","zh-TW":"由於市場不確定性，第三季度的銷售額下滑。"}]', '{"noun":"flagging","adjective":"flagging"}', '動詞 flag 表示「精力/興趣衰退」或「標記」，與旗子完全無關，常見於 TOEIC 閱讀描述業務下滑或編輯流程的文章中。', 1, 893),
(894, 'flexible', '/ˈfleksəbəl/', 'adjective', '{"zh-TW":["靈活的；彈性的","靈活的；有彈性的"],"en":["able to change or be changed easily","capable of bending easily","willing to change or compromise"]}', '{"root":{"text":"flex","meaning":"bend (彎曲)"},"suffix":{"text":"-ible","meaning":"able to (能夠)"},"logic":"能夠彎曲的，即「靈活的」。"}', 'flexible schedule/hours; flexible schedule / flexible approach', '[{"en":"We offer flexible working hours.","zh-TW":"我們提供彈性工作時間。"},{"en":"The policy needs to be more flexible.","zh-TW":"政策需要更加靈活。"},{"en":"We need a more flexible approach.","zh-TW":"我們需要更靈活的做法。"},{"en":"The company offers flexible working hours.","zh-TW":"公司提供彈性工作時間。"}]', '{"noun":"flexibility","adjective":"flexible","adverb":"flexibly"}', NULL, 3, 894),
(895, 'float', '/floʊt/', 'verb', '{"zh-TW":["浮動；漂浮"],"en":["to rest on the surface; to allow exchange rate to vary"]}', NULL, 'float on the market', '[{"en":"The company floated on the stock exchange.","zh-TW":"公司在股票交易所上市。"},{"en":"The currency was allowed to float freely.","zh-TW":"貨幣被允許自由浮動。"}]', '{"noun":"flotation","verb":"float","adjective":"floating"}', NULL, 2, 895),
(896, 'flood', '/flʌd/', 'noun', '{"zh-TW":["洪水"],"en":["an overflow of water onto normally dry land"]}', '{"root":{"text":"flood","meaning":"flow (流動)"},"logic":"源自古英語 flōd（大水流動）。"}', 'flash flood / flood damage / flood warning', '[{"en":"The flood destroyed hundreds of homes.","zh-TW":"洪水摧毀了數百戶房屋。"},{"en":"Heavy rains caused severe flooding in the area.","zh-TW":"大雨在該地區造成嚴重水災。"}]', '{"verb":"flood","noun":"flooding"}', NULL, 2, 896),
(897, 'floor', '/flɔːr/', 'noun', '{"zh-TW":["地板；樓層"],"en":["the lower surface of a room","a level of a building"]}', NULL, 'ground floor / sales floor', '[{"en":"The office is on the third floor.","zh-TW":"辦公室在三樓。"},{"en":"The sales floor is very spacious.","zh-TW":"銷售樓層很寬敞。"}]', '{"noun":"floor","noun2":"flooring"}', NULL, 2, 897),
(898, 'flourish', '/ˈflɜːrɪʃ/', 'verb', '{"zh-TW":["繁榮；蓬勃發展"],"en":["to grow or develop successfully"]}', NULL, 'business flourishes', '[{"en":"The business flourished under new management.","zh-TW":"在新管理層下企業蓬勃發展。"},{"en":"Creativity flourishes in a supportive environment.","zh-TW":"創造力在支持性環境中蓬勃發展。"}]', '{"verb":"flourish","adjective":"flourishing"}', NULL, 3, 898),
(899, 'flow', '/floʊ/', 'noun / verb', '{"zh-TW":["流動；流程"],"en":["the movement of something; to move steadily"]}', NULL, 'cash flow / workflow', '[{"en":"The company has positive cash flow.","zh-TW":"公司有正向的現金流。"},{"en":"Information flows between departments.","zh-TW":"資訊在部門間流動。"}]', '{"noun":"flow","verb":"flow"}', NULL, 1, 899);
