(939, 'fundamental', '/ˌfʌndəˈmentəl/', 'adjective', '{"zh-TW":["基本的；根本的"],"en":["forming a necessary base; essential"]}', '{"root":{"text":"fund","meaning":"bottom/foundation (基礎)"},"suffix":{"text":"-amental","meaning":"relating to (相關的)"},"logic":"與基礎相關的，即「根本的」。"}', 'fundamental change/principle; fundamental principle / fundamental change / fundamental right', '[{"en":"Trust is fundamental to any business relationship.","zh-TW":"信任是任何商業關係的根本。"},{"en":"There are fundamental differences between the two plans.","zh-TW":"兩個計畫之間有根本的差異。"},{"en":"Respect is fundamental to any relationship.","zh-TW":"尊重是任何關係的根本。"},{"en":"There has been a fundamental change in policy.","zh-TW":"政策發生了根本性的改變。"}]', '{"noun":"fundamentals","adjective":"fundamental","adverb":"fundamentally"}', NULL, 4, 939),
(940, 'funny', '/ˈfʌni/', 'adjective', '{"zh-TW":["有趣的；好笑的"],"en":["causing laughter","strange or unexpected"]}', NULL, 'funny story / look funny', '[{"en":"He told a funny story at the dinner.","zh-TW":"他在晚餐上說了一個有趣的故事。"},{"en":"Something looks funny about these numbers.","zh-TW":"這些數字看起來有點奇怪。"}]', '{"adjective":"funny","adverb":"funnily","noun":"fun"}', NULL, 2, 940),
(941, 'furnish', '/ˈfɜːrnɪʃ/', 'verb', '{"zh-TW":["提供；配備"],"en":["to supply or provide; to equip with furniture"]}', NULL, 'furnish information/an office', '[{"en":"The apartment is fully furnished.","zh-TW":"公寓配備齊全。"},{"en":"Please furnish the required documents.","zh-TW":"請提供所需文件。"}]', '{"noun":"furnishing/furniture","verb":"furnish","adjective":"furnished"}', NULL, 3, 941),
(942, 'further', '/ˈfɜːrðər/', 'adverb / adjective / verb', '{"zh-TW":["進一步的；促進"],"en":["to a greater extent; to advance"]}', NULL, 'further information/investigation', '[{"en":"For further information, contact our office.","zh-TW":"如需進一步資訊，請聯繫我們的辦公室。"},{"en":"Education furthers career advancement.","zh-TW":"教育促進職業發展。"}]', '{"adjective":"further","adverb":"further/furthermore","verb":"further"}', NULL, 3, 942),
(943, 'furthermore', '/ˌfɜːrðərˈmɔːr/', 'adverb', '{"zh-TW":["此外；而且"],"en":["in addition to what has been said"]}', NULL, 'furthermore, ...', '[{"en":"The plan is cost-effective; furthermore, it is easy to implement.","zh-TW":"該計畫具有成本效益；此外，它易於實施。"},{"en":"Furthermore, the data supports our conclusion.","zh-TW":"此外，數據支持我們的結論。"}]', '{"adverb":"furthermore"}', NULL, 4, 943),
