(947, 'gallery', '/ˈɡæləri/', 'noun', '{"zh-TW":["畫廊；美術館"],"en":["a room or building for displaying works of art"]}', '{"root":{"text":"gallery","meaning":"porch/corridor (走廊)"},"logic":"源自中世紀拉丁語 galeria（走廊），後指展示藝術品的空間。"}', 'art gallery / photo gallery', '[{"en":"We visited an art gallery downtown.","zh-TW":"我們參觀了市中心的一家畫廊。"},{"en":"The gallery features local artists.","zh-TW":"這家畫廊展出本地藝術家的作品。"}]', NULL, NULL, 3, 947),
